F=Fig('arrow178');t=F.t;line=F.line
paras=[];layout=[];blocks=[]
def add(e,u,p,kind='paragraph'):
 layout.append({'type':kind,'indices':[len(paras)]});paras.append(pair(e,u,p))
def lines(rows,kind='lines'):
 s0=len(paras)
 for r in rows:paras.append(pair(*r))
 layout.append({'type':kind,'indices':list(range(s0,len(paras)))})
def visual(identity,fn):
 blocks.append({'id':identity,'svg':fn('en'),'svgUrdu':fn('ur'),'svgPashto':fn('ps')});layout.append({'type':'visual','blockId':identity})
K=lambda lang,*v:v[{'en':0,'ur':1,'ps':2}[lang]]
def plant(lang):
 st=[('Pipes take water to treatment center','پائپ پانی کو صفائی مرکز لے جاتے ہیں','نلونه اوبه د درملنې مرکز ته وړي'),('Screening stage','چھاننے کا مرحلہ','د چاڼ پړاو'),('Primary Treatment stage','ابتدائی صفائی کا مرحلہ','د لومړنۍ درملنې پړاو'),('Secondary Treatment stage','ثانوی صفائی کا مرحلہ','د دویمې درملنې پړاو'),('Final Treatment stage','آخری صفائی کا مرحلہ','د وروستۍ درملنې پړاو'),('Filtered into river','چھان کر دریا میں','فلټر شوې سیند ته')]
 s=F.start(240)+'<rect x="0" y="150" width="850" height="90" fill="#8d6e63"/><rect x="0" y="0" width="850" height="150" fill="#c8e6c9"/>'
 xs=[70,210,350,490,630,780]
 s+='<rect x="30" y="80" width="80" height="70" fill="#a1887f"/>'+'<rect x="185" y="150" width="50" height="60" fill="#cfd8dc" stroke="#555"/>'+''.join(line(192+k*9,152,192+k*9,208,1.5,'#555') for k in range(5))
 s+='<ellipse cx="350" cy="170" rx="55" ry="18" fill="#795548" stroke="#333"/><rect x="480" y="60" width="20" height="150" fill="#6d4c41"/><ellipse cx="630" cy="165" rx="50" ry="16" fill="#795548" stroke="#333"/><path d="M720 200 Q780 160 850 190 L850 240 L720 240 Z" fill="#42a5f5"/>'
 s+=line(110,190,820,190,6,'#1e88e5')
 for (a,b,c),x in zip(st,xs):
  w=(a,b,c)[{'en':0,'ur':1,'ps':2}[lang]].split(' ');half=len(w)//2 or 1
  s+=t(x,24,' '.join(w[:half]),11)+t(x,38,' '.join(w[half:]),11)
 return s+'</svg>'

add('Total suspended Solids (TSS): It gives the amount of filterable solid in water sample.','کل معلق ٹھوس (TSS): یہ پانی کے نمونے میں قابلِ چھنائی ٹھوس کی مقدار بتاتا ہے۔','ټول ځړېدلي جامدات (TSS): د اوبو په نمونه کې د فلټر وړ جامداتو اندازه ښيي.','list')
lines([('Total Dissolved Solids (TDS): It shows the presence of non-filterable material in water sample that pass through the filtering apparatus.','کل حل شدہ ٹھوس (TDS): یہ پانی کے نمونے میں ناقابلِ چھنائی مادے کی موجودگی ظاہر کرتا ہے جو چھاننے کے آلے سے گزر جاتا ہے۔','ټول حل شوي جامدات (TDS): د اوبو په نمونه کې د هغه نه فلټر کېدونکي توکي شتون ښيي چې د فلټر له وسیلې تېرېږي.'),
 ('pH: It shows the intensity of acidity or alkalinity of water. The recommended pH range is slightly alkaline (pH = 7.0 – 8.5).','pH: یہ پانی کی تیزابیت یا اساسیت کی شدت ظاہر کرتا ہے۔ تجویز کردہ pH کی حد ہلکی اساسی (pH = 7.0 – 8.5) ہے۔','pH: د اوبو د تېزابیت یا قلویت شدت ښيي. سپارښتل شوې pH پوله لږ قلوي (pH = 7.0 – 8.5) ده.'),
 ('BOD: Biological Oxygen Demand, represents amount of oxygen required by living organism to survive and for oxidation of biodegradable organic matter present in water under aerobic condition. It is an indirect measurement of quantity of bio-degradable organic matter in water.','BOD: حیاتیاتی آکسیجن کی طلب، آکسیجن کی وہ مقدار ظاہر کرتی ہے جو جانداروں کو زندہ رہنے اور ہوائی حالت میں پانی میں موجود حیاتیاتی طور پر تحلیل ہونے والے نامیاتی مادے کی تکسید کے لیے درکار ہے۔ یہ پانی میں حیاتیاتی طور پر تحلیل ہونے والے نامیاتی مادے کی مقدار کی بالواسطہ پیمائش ہے۔','BOD: بیولوژیکي اکسیجن غوښتنه، د اکسیجن هغه اندازه ښيي چې ژوندي موجودات یې د ژوندي پاتې کېدو او په هوايي حالت کې په اوبو کې د شته بیولوژیکي تجزیه کېدونکې عضوي مادې د اکسیډېشن لپاره اړتیا لري. دا په اوبو کې د بیولوژیکي تجزیه کېدونکې عضوي مادې د اندازې غیر مستقیم اندازه ده.'),
 ('Chemical Oxygen Demand (COD): It is amount of oxygen needed for oxidation of toxic organic matter present in water by strong chemical oxidizing agents such as K₂Cr₂O₇.','کیمیائی آکسیجن کی طلب (COD): یہ آکسیجن کی وہ مقدار ہے جو پانی میں موجود زہریلے نامیاتی مادے کی K₂Cr₂O₇ جیسے طاقتور کیمیائی تکسیدی عاملوں سے تکسید کے لیے درکار ہے۔','کیمیاوي اکسیجن غوښتنه (COD): د اکسیجن هغه اندازه ده چې په اوبو کې د شته زهرجنې عضوي مادې د قوي کیمیاوي اکسیډایز کوونکو عاملونو لکه K₂Cr₂O₇ په واسطه د اکسیډېشن لپاره اړینه ده.'),
 ('Dissolved Oxygen (DO): Dissolved oxygen provides a source of oxygen for aquatic aerobic (oxygen requiring) organism like fish, aerobic bacteria.','حل شدہ آکسیجن (DO): حل شدہ آکسیجن مچھلی اور ہوائی بیکٹیریا جیسے آبی ہوائی (آکسیجن کے محتاج) جانداروں کے لیے آکسیجن کا ذریعہ ہے۔','حل شوی اکسیجن (DO): حل شوی اکسیجن د اوبلنو هوايي (اکسیجن ته اړ) ژوندیو لکه کبانو او هوايي باکتریاوو لپاره د اکسیجن سرچینه برابروي.'),
 ('Total Organic Carbon (TOC): Water purity is critical for a number of industries such as pharmaceutical and semiconductor manufacturing etc. The presence of bacteria and other organic compounds in water can create significant challenges like negative impact on product quality and profitability. The total organic carbon (TOC) analysis is the standard test for quality and purity of water. It simply measures the carbon found in any organic compound in water, it is not able to indicate the type of organic molecule present.','کل نامیاتی کاربن (TOC): ادویہ سازی اور سیمی کنڈکٹر سازی وغیرہ جیسی کئی صنعتوں کے لیے پانی کی خالصیت نہایت اہم ہے۔ پانی میں بیکٹیریا اور دوسرے نامیاتی مرکبات کی موجودگی پروڈکٹ کے معیار اور منافع پر منفی اثر جیسے بڑے چیلنج پیدا کر سکتی ہے۔ کل نامیاتی کاربن (TOC) کا تجزیہ پانی کے معیار اور خالصیت کا معیاری ٹیسٹ ہے۔ یہ پانی میں کسی بھی نامیاتی مرکب میں پایا جانے والا کاربن ناپتا ہے، یہ موجود نامیاتی سالمے کی قسم نہیں بتا سکتا۔','ټول عضوي کاربن (TOC): د اوبو خالصوالی د یو شمېر صنعتونو لکه درمل جوړونې او سیمي کنډکټر جوړونې او نورو لپاره ډېر مهم دی. په اوبو کې د باکتریاوو او نورو عضوي مرکباتو شتون کولی شي د محصول پر کیفیت او ګټې منفي اغېز په څېر لویې ننګونې رامنځته کړي. د ټول عضوي کاربن (TOC) تحلیل د اوبو د کیفیت او خالصوالي معیاري ازموینه ده. دا یوازې په اوبو کې په هر عضوي مرکب کې موندل شوی کاربن اندازه کوي، د شته عضوي مالیکول ډول نه شي ښودلی.')],'list')
add('23.3.2 Wastewater Treatment','23.3.2 گندے پانی کی صفائی','23.3.2 د ککړو اوبو درملنه','heading')
add('The wastewater is full of contaminants such as chemicals, bacteria, and other pollutants. The wastewater treatment is a process used to remove contaminants from wastewater or sewage and convert it into an effluent that can be returned to water cycle with minimum impact on the environment. The following treatment process takes place in wastewater treatment plant.','گندا پانی کیمیکلز، بیکٹیریا اور دوسری آلودگیوں سے بھرا ہوتا ہے۔ گندے پانی کی صفائی وہ عمل ہے جس سے گندے پانی یا سیوریج سے آلودگیاں نکال کر اسے ایسے اخراجی پانی میں بدلا جاتا ہے جو ماحول پر کم سے کم اثر کے ساتھ آبی چکر میں واپس جا سکے۔ گندے پانی کی صفائی کے پلانٹ میں درج ذیل صفائی کا عمل ہوتا ہے۔','ککړې اوبه له کیمیکلونو، باکتریاوو او نورو ککړوونکو ډکې وي. د ککړو اوبو درملنه هغه عملیه ده چې له ککړو اوبو یا فاضله اوبو څخه ککړوونکي لرې کوي او په داسې خوشې شوو اوبو یې بدلوي چې د چاپېریال پر لږترلږه اغېز سره د اوبو دورې ته بېرته ورکول کېدای شي. د ککړو اوبو د درملنې په فابریکه کې لاندې د درملنې عملیه ترسره کېږي.')
lines([('Stage-I: Screening: Screening or filtering removes large floating solid objects like broken bottles, plastic objects, shopping bags, cloth pieces, stones etc. that may block or damage the equipment.','مرحلہ I: چھنائی: چھنائی یا فلٹرنگ بڑی تیرتی ٹھوس اشیا جیسے ٹوٹی بوتلیں، پلاسٹک کی اشیا، شاپنگ بیگ، کپڑے کے ٹکڑے، پتھر وغیرہ نکالتی ہے جو آلات کو بند یا خراب کر سکتی ہیں۔','پړاو I: چاڼ: چاڼ یا فلټر کول لوی لامبو وهونکي جامد شیان لکه مات بوتلونه، پلاستیکي شیان، د پېرودنې کڅوړې، د ټوکر ټوټې، ډبرې او نور لرې کوي چې کېدای شي وسایل بند یا زیانمن کړي.'),
 ('Stage-II: Primary Treatment: It involves the treatment of solid organic matter from the wastewater by putting the wastewater into large settlement tanks. The finer, colloidal particles that make water turbid, cannot be removed by simple filtration. So, a flocculating agent that is a substance which forms large gelatinous particles, is added. The common flocculating agent is aluminum sulphate, Al₂(SO₄)₃, often referred to as alum, some lime, Ca(OH)₂, is generally also added so that precipitate of aluminium hydroxide, Al(OH)₃ which has the desired gelatinous form, is produced.','مرحلہ II: ابتدائی صفائی: اس میں گندے پانی کو بڑے تہہ نشینی ٹینکوں میں ڈال کر اس سے ٹھوس نامیاتی مادے کی صفائی شامل ہے۔ پانی کو گدلا بنانے والے باریک کولائیڈل ذرات سادہ چھنائی سے نہیں نکالے جا سکتے۔ اس لیے ایک فلوکولیٹنگ عامل، یعنی ایسا مادہ جو بڑے جیلیٹینی ذرات بناتا ہے، شامل کیا جاتا ہے۔ عام فلوکولیٹنگ عامل ایلومینیم سلفیٹ Al₂(SO₄)₃ ہے جسے اکثر پھٹکری کہتے ہیں، اور عموماً کچھ چونا Ca(OH)₂ بھی ڈالا جاتا ہے تاکہ ایلومینیم ہائیڈروآکسائیڈ Al(OH)₃ کا رسوب بنے جس کی مطلوبہ جیلیٹینی صورت ہو۔','پړاو II: لومړنۍ درملنه: د ککړو اوبو په لویو ټانکونو کې اچولو سره له هغو څخه د جامدې عضوي مادې درملنه پکې شامله ده. هغه نرۍ کولایډي ذرې چې اوبه خړې کوي په ساده فلټر نه شي لرې کېدای. نو یو فلوکولېټنګ عامل، یعنې هغه ماده چې لویې جیلاټیني ذرې جوړوي، ورزیاتېږي. عام فلوکولېټنګ عامل المونیم سلفېټ Al₂(SO₄)₃ دی چې ډېری زاج بلل کېږي، او عموماً لږ چونه Ca(OH)₂ هم ورزیاتېږي څو د المونیم هایدروکساید Al(OH)₃ رسوب جوړ شي چې غوښتل شوې جیلاټیني بڼه ولري.')],'list')
visual('chem12-p178-alum',lambda l:F.start(70)+t(300,36,'Al₂(SO₄)₃ + 3Ca(OH)₂',16)+F.arrow(420,510,30)+t(630,36,'2Al(OH)₃(ppt) + 3CaSO₄',16)+'</svg>')
add('This precipitate traps both inorganic solid particles and bacteria in the large curd like particles. These particles are then easily removed by filtration through a sand-bed or charcoal. Some heavy particles sink to the bottom, which is called ‘sludge’. It is further treated separately.','یہ رسوب غیر نامیاتی ٹھوس ذرات اور بیکٹیریا دونوں کو بڑے دہی جیسے ذرات میں قید کر لیتا ہے۔ پھر یہ ذرات ریت کے بستر یا کوئلے سے چھان کر آسانی سے نکال دیے جاتے ہیں۔ کچھ بھاری ذرات تہہ میں بیٹھ جاتے ہیں جسے ’سلج‘ کہتے ہیں۔ اسے الگ سے مزید صاف کیا جاتا ہے۔','دا رسوب غیر عضوي جامدې ذرې او باکتریا دواړه په لویو د مستو په څېر ذرو کې بندوي. بیا دا ذرې د شګو د بستر یا سکرو له لارې په فلټر کولو په اسانۍ لرې کېږي. ځینې درنې ذرې تل ته کښېني چې ’سلج‘ بلل کېږي. دا په جلا توګه نوره درملنه کېږي.')
lines([('Stage III: Secondary Treatment: The water at this stage is put into large rectangular tanks, where air is pumped into the water so that the bacteria break down the tiny bits of sludge.','مرحلہ III: ثانوی صفائی: اس مرحلے پر پانی کو بڑے مستطیل ٹینکوں میں ڈالا جاتا ہے جہاں پانی میں ہوا پمپ کی جاتی ہے تاکہ بیکٹیریا سلج کے چھوٹے ٹکڑوں کو توڑ دیں۔','پړاو III: دویمه درملنه: په دې پړاو کې اوبه په لویو مستطیلي ټانکونو کې اچول کېږي چې هلته اوبو ته هوا پمپ کېږي څو باکتریا د سلج کوچنۍ ټوټې مات کړي.'),
 ('Stage IV: Tertiary or Final Treatment: Next, the almost treated wastewater is passed through a settlement tank. Here, more sludge is formed at the bottom of the tank from the settlement of the bacterial action. Again, the sludge is scraped and collected for treatment. The water at this stage is almost free from harmful substances and chemicals. The water is filtered to remove additional particles.','مرحلہ IV: ثالثی یا آخری صفائی: اس کے بعد تقریباً صاف شدہ گندا پانی ایک تہہ نشینی ٹینک سے گزارا جاتا ہے۔ یہاں بیکٹیریائی عمل کے تہہ نشین ہونے سے ٹینک کی تہہ میں مزید سلج بنتا ہے۔ دوبارہ سلج کو کھرچ کر صفائی کے لیے جمع کیا جاتا ہے۔ اس مرحلے پر پانی نقصان دہ مادوں اور کیمیکلز سے تقریباً پاک ہوتا ہے۔ اضافی ذرات نکالنے کے لیے پانی کو چھانا جاتا ہے۔','پړاو IV: درېیمه یا وروستۍ درملنه: ورپسې نږدې درملنه شوې ککړې اوبه د یوه کښېنستو ټانک له لارې تېرېږي. دلته د باکتریايي عمل له کښېنستو څخه د ټانک په تل کې نور سلج جوړېږي. بیا سلج کرېږل کېږي او د درملنې لپاره راټولېږي. په دې پړاو کې اوبه له زیانمنو موادو او کیمیکلونو نږدې پاکې وي. د اضافي ذرو د لرې کولو لپاره اوبه فلټر کېږي.')],'list')
add('After that the filtered water is discharged into river. If water is treated for drinking purposes then it is passed through a process of disinfection using chlorination, ozone treatment and ultraviolet light etc. to eliminate disease causing organisms. Chlorination is the widely used method to disinfect water.','اس کے بعد چھانا ہوا پانی دریا میں چھوڑ دیا جاتا ہے۔ اگر پانی پینے کے لیے صاف کیا جا رہا ہو تو بیماری پیدا کرنے والے جانداروں کو ختم کرنے کے لیے اسے کلورینیشن، اوزون سے صفائی اور بالائے بنفشی روشنی وغیرہ سے جراثیم کشی کے عمل سے گزارا جاتا ہے۔ کلورینیشن پانی کو جراثیم سے پاک کرنے کا وسیع پیمانے پر استعمال ہونے والا طریقہ ہے۔','له هغه وروسته فلټر شوې اوبه سیند ته خوشې کېږي. که اوبه د څښلو لپاره درملنه کېږي، نو د ناروغي راوړونکو ژوندیو د له منځه وړلو لپاره د کلورینېشن، اوزون درملنې او ماورای بنفش رڼا او نورو په کارولو د مکروب وژنې له عملیې تېرېږي. کلورینېشن د اوبو د مکروب وژنې په پراخه کچه کارېدونکې طریقه ده.')
